mapper.insert:
INSERT INTO community_report_images (
    report_id,
    image_url,
    display_order
) VALUES (
    #{reportId},
    #{imageUrl},
    #{displayOrder}
)

mapper.select:
SELECT
    ri.report_image_id AS reportImageId,
    ri.report_id AS reportId,
    ri.image_url AS imageUrl,
    ri.display_order AS displayOrder
FROM community_report_images ri
INNER JOIN community_reports r ON r.report_id = ri.report_id
WHERE ri.report_id = #{reportId}
    AND ri.report_image_id = #{reportImageId}
    AND r.reporter_member_id = #{reporterMemberId}
